/**
 * SenseNova U1.6 Lite text-to-image tool with 6.8 Flash visual checks.
 *
 * The model is an image-generation model served by an OpenAI-compatible
 * `/v1/images/generations` endpoint; it has no chat-completions route. This
 * plugin exposes it to every DSH agent (root and subagents) as one tool,
 * downloads the generated bytes, saves them in the session working directory,
 * and returns absolute paths plus ready-to-use Markdown.
 */

import { randomUUID } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { extname, isAbsolute, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import z from '@deepseek-ai/schemastery'
import { defineTool, ToolArgsError } from '@deepseek-ai/dsh-tools'

export const name = 'sensenova-image'
export const inject = ['tools', 'workingDirectory']

const DEFAULT_BASE_URL = 'https://token.sensenova.cn/v1'
const DEFAULT_MODEL = 'sensenova-u1.6-lite'
const VISION_MODEL = 'sensenova-6.8-flash'
const DEFAULT_API_KEY_ENV = 'SENSENOVA_API_KEY'
/** Optional user-supplied key; when configured it outranks `apiKeyEnv`. */
const USER_API_KEY_ENV = 'SENSENOVA_IMAGE_API_KEY'
const DEFAULT_OUTPUT_DIR = 'generated-images'
const DEFAULT_REQUEST_TIMEOUT_MS = 300_000
const TOOL_TIMEOUT_MS = 480_000
const VISION_TIMEOUT_MS = 60_000
const MAX_IMAGES = 4
const MAX_REFERENCE_IMAGES = 5

const OUTPUT_FORMATS = {
  png: 'image/png',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
}

/**
 * Live plugin configuration.
 *
 * Request defaults are volatile: the settings page writes them into the active
 * profile entry, and the tool reads them at call time. `apiKeyEnv`, `baseURL`
 * and `requestTimeoutMs` stay ordinary because they are deployment wiring, not
 * per-image choices.
 */
export const Config = z.object({
  apiKeyEnv: z.string().default(DEFAULT_API_KEY_ENV),
  baseURL: z.string().default(DEFAULT_BASE_URL),
  model: z.string().default(DEFAULT_MODEL).volatile(),
  keyPreference: z.string().default('custom').volatile(),
  size: z.string().default('auto').volatile(),
  n: z.number().step(1).min(1).max(MAX_IMAGES).default(1).volatile(),
  watermark: z.boolean().default(false).volatile(),
  prompt_extend: z.boolean().default(true).volatile(),
  self_correction: z.boolean().default(true).volatile(),
  verify: z.boolean().default(true).volatile(),
  output_format: z.string().default('png').volatile(),
  outputDir: z.string().default(DEFAULT_OUTPUT_DIR).volatile(),
  requestTimeoutMs: z.number().default(DEFAULT_REQUEST_TIMEOUT_MS),
})

function textConfig(config, key, fallback) {
  const value = config?.[key]
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : fallback
}

function numberConfig(config, key, fallback) {
  const value = config?.[key]
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback
}

/** Read a volatile Config field, or a plain value in tests and older profiles. */
function liveConfig(config, key, fallback) {
  const field = config?.[key]
  const value = field !== null && typeof field === 'object' && typeof field.get === 'function'
    ? field.get()
    : field
  return value === undefined ? fallback : value
}

/** Turn a prompt or requested filename into a short, filesystem-safe stem. */
function safeStem(value, fallback) {
  const cleaned = String(value ?? '')
    .normalize('NFKC')
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
  return cleaned === '' ? fallback : cleaned
}

/** Validate the API's size syntax before spending a request. */
function normalizeSize(raw) {
  const size = typeof raw === 'string' && raw.trim() !== '' ? raw.trim() : 'auto'
  if (size.toLowerCase() === 'auto') return 'auto'
  if (/^(2k|4k)$/i.test(size)) return size.toUpperCase()
  const match = /^(\d{3,4})x(\d{3,4})$/i.exec(size)
  if (match === null) {
    throw new ToolArgsError(['size must be "2K", "4K", or WIDTHxHEIGHT such as "2048x2048"'])
  }
  const width = Number(match[1])
  const height = Number(match[2])
  const problems = []
  if (width < 512 || width > 4096 || height < 512 || height > 4096) {
    problems.push('width and height must be between 512 and 4096')
  }
  if (width % 32 !== 0 || height % 32 !== 0) problems.push('width and height must be multiples of 32')
  if (Math.max(width, height) / Math.min(width, height) > 3) problems.push('the aspect ratio cannot exceed 3:1')
  if (problems.length > 0) throw new ToolArgsError(problems)
  return `${width}x${height}`
}

/** Resolve one credential reference from the DSH credential store, then the launch environment. */
async function resolveKeyRef(ctx, ref) {
  const credentials = ctx.get('credentials')
  if (credentials !== undefined) {
    const hit = await credentials.resolve(ref)
    if (hit !== undefined && typeof hit.value === 'string' && hit.value.trim() !== '') return hit.value.trim()
  }
  const fromEnvironment = process.env[ref]
  if (typeof fromEnvironment === 'string' && fromEnvironment.trim() !== '') return fromEnvironment.trim()
  return undefined
}

/** Whether an API failure should be retried with another configured key. */
function isKeyFailoverError(status, payload, raw) {
  if (status === 401 || status === 402 || status === 403 || status === 429) return true
  const text = `${payload?.error?.message ?? ''} ${payload?.error?.code ?? ''} ${payload?.error?.type ?? ''} ${raw ?? ''}`.toLowerCase()
  return /quota|insufficient|balance|credit|rate.?limit|too many|exceeded|exhausted|积分|额度|5\s*hour|窗口/u.test(text)
}

/**
 * Resolve the configured keys in the selected preference order. Duplicate
 * values collapse to one entry; the caller may use the second entry when the
 * first is rate-limited or out of quota.
 */
async function resolveApiKeys(ctx, ref, preference = 'custom') {
  const custom = await resolveKeyRef(ctx, USER_API_KEY_ENV)
  const fallback = await resolveKeyRef(ctx, ref)
  const ordered = preference === 'default' ? [fallback, custom] : [custom, fallback]
  const keys = []
  for (const key of ordered) {
    if (typeof key === 'string' && key !== '' && !keys.includes(key)) keys.push(key)
  }
  if (keys.length === 0) {
    throw new Error(
      `sensenova_generate_image: no API key; set ${USER_API_KEY_ENV} in Settings, `
      + `or configure ${ref} in the DSH credential store / environment`,
    )
  }
  return keys
}

/** Best-effort persistence of the key that actually served the image request. */
async function persistKeyPreference(ctx, successKey, customKey, fallbackKey) {
  const preference = successKey === customKey ? 'custom' : successKey === fallbackKey ? 'default' : undefined
  if (preference === undefined) return
  const settings = ctx.get('settings')
  if (settings === undefined) return
  try {
    await settings.mutate('sensenova-image', [{ op: 'set', path: ['keyPreference'], value: preference }])
  } catch (_failure) {
    // The request already succeeded; a failed preference write must not fail it.
  }
}

/** One generation/editing request with one key. */
async function requestImagesOnce({ baseURL, apiKey, path, body, signal, timeoutMs }) {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new Error(`request timed out after ${timeoutMs} ms`)), timeoutMs)
  const forwardAbort = () => controller.abort(signal.reason)
  signal.addEventListener('abort', forwardAbort, { once: true })
  try {
    const response = await fetch(`${baseURL.replace(/\/+$/u, '')}${path}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    })
    const raw = await response.text()
    let payload
    try {
      payload = raw === '' ? undefined : JSON.parse(raw)
    } catch (_failure) {
      payload = undefined
    }
    if (!response.ok) {
      const detail = payload?.error?.message ?? payload?.message ?? raw.slice(0, 500)
      return {
        ok: false,
        retryable: isKeyFailoverError(response.status, payload, raw),
        error: new Error(`sensenova_generate_image: HTTP ${response.status} from ${path}: ${detail}`),
      }
    }
    if (payload === undefined || !Array.isArray(payload.data) || payload.data.length === 0) {
      return { ok: false, retryable: false, error: new Error('sensenova_generate_image: the API returned no image data') }
    }
    return { ok: true, payload }
  } catch (error) {
    return {
      ok: false,
      retryable: false,
      error: error instanceof Error ? error : new Error(String(error)),
    }
  } finally {
    clearTimeout(timer)
    signal.removeEventListener('abort', forwardAbort)
  }
}

/**
 * POST one image request, trying each configured key in order when the
 * previous key is rate-limited, out of quota, or rejected.
 * @returns the successful payload and the key that served it.
 */
async function requestImages({ baseURL, apiKeys, path, body, signal, timeoutMs }) {
  let last
  for (const apiKey of apiKeys) {
    const result = await requestImagesOnce({ baseURL, apiKey, path, body, signal, timeoutMs })
    if (result.ok) return { payload: result.payload, apiKey }
    last = result
    if (!result.retryable) throw result.error
  }
  throw last?.error ?? new Error('sensenova_generate_image: all configured API keys failed')
}

/** Read one image's bytes from the API's URL or inline Base64 form. */
async function readImageBytes(item, signal) {
  if (typeof item.b64_json === 'string' && item.b64_json !== '') {
    return Buffer.from(item.b64_json, 'base64')
  }
  if (typeof item.url === 'string' && item.url !== '') {
    const response = await fetch(item.url, { signal })
    if (!response.ok) {
      throw new Error(
        `sensenova_generate_image: could not download the generated image (HTTP ${response.status}); `
        + `the temporary URL is ${item.url}`,
      )
    }
    return Buffer.from(await response.arrayBuffer())
  }
  throw new Error('sensenova_generate_image: the API returned neither url nor b64_json')
}

const REFERENCE_MIME = {
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
}
const MAX_REFERENCE_BYTES = 10 * 1024 * 1024

/** Turn a public URL, data URL, or local file path into an API image_url. */
async function resolveReferenceImage(value, ctx, session) {
  const input = value.trim()
  if (/^https?:\/\//iu.test(input) || /^data:image\//iu.test(input)) return input
  let path = input
  if (/^file:\/\//iu.test(input)) {
    try {
      path = fileURLToPath(input)
    } catch (_failure) {
      throw new ToolArgsError([`invalid file URL: ${input}`])
    }
  }
  let cwd = ctx.workingDirectory.defaultDirectory
  if (session !== undefined) {
    try {
      cwd = ctx.workingDirectory.get(session)
    } catch (_failure) {
      // fall back to the default directory
    }
  }
  const absolute = isAbsolute(path) ? path : resolve(cwd, path)
  let bytes
  try {
    bytes = await readFile(absolute)
  } catch (error) {
    throw new ToolArgsError([`cannot read reference image ${absolute}: ${error instanceof Error ? error.message : String(error)}`])
  }
  if (bytes.byteLength > MAX_REFERENCE_BYTES) {
    throw new ToolArgsError([`reference image is larger than 10 MB: ${absolute}`])
  }
  const mime = REFERENCE_MIME[extname(absolute).toLowerCase()]
  if (mime === undefined) {
    throw new ToolArgsError([`unsupported reference image type (use png, jpeg, or webp): ${absolute}`])
  }
  return `data:${mime};base64,${bytes.toString('base64')}`
}

/** Extract the JSON verdict from a vision reply, tolerating code fences and prose. */
function parseVerdict(content) {
  const text = typeof content === 'string' ? content.trim() : ''
  if (text === '') return undefined
  const fenced = text.replace(/^```(?:json)?\s*/iu, '').replace(/\s*```$/u, '')
  try { return JSON.parse(fenced) } catch (_failure) { /* fall through */ }
  const start = fenced.indexOf('{')
  const end = fenced.lastIndexOf('}')
  if (start !== -1 && end > start) {
    try { return JSON.parse(fenced.slice(start, end + 1)) } catch (_failure) { /* fall through */ }
  }
  return undefined
}

function normalizeVerdict(value) {
  return value === 'pass' || value === 'warn' || value === 'fail' ? value : 'warn'
}

/**
 * Ask `sensenova-6.8-flash` to check one generated image against the prompt.
 * The key and base URL are the same as the image call; a failure is reported
 * in the result instead of discarding the image.
 */
const VISION_MODELS = ['sensenova-6.8-flash', 'sensenova-6.8-flash-lite']

/** Send one vision request and classify its answer for the fallback chain. */
async function requestVision({ baseURL, apiKey, model, imageUrl, prompt, signal, timeoutMs }) {
  const instruction = [
    '你是严格的图像质检员。只输出 JSON，不要输出其他文字。',
    `用户要求：${prompt}`,
    '请核对这张生成图是否满足要求，检查主体、颜色、构图、文字和明显瑕疵。',
    '输出 JSON：{"verdict":"pass|warn|fail","summary":"一句话结论","issues":["问题1"]}。',
  ].join('\n')
  const body = {
    model,
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: instruction },
        { type: 'image_url', image_url: { url: imageUrl } },
      ],
    }],
    max_tokens: 800,
    temperature: 0.1,
  }
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new Error(`vision request timed out after ${timeoutMs} ms`)), timeoutMs)
  const forwardAbort = () => controller.abort(signal.reason)
  signal.addEventListener('abort', forwardAbort, { once: true })
  try {
    const response = await fetch(`${baseURL.replace(/\/+$/u, '')}/chat/completions`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    })
    const raw = await response.text()
    let payload
    try {
      payload = raw === '' ? undefined : JSON.parse(raw)
    } catch (_failure) {
      payload = undefined
    }
    if (!response.ok) {
      const detail = payload?.error?.message ?? payload?.message ?? raw.slice(0, 300)
      return { ok: false, model, status: response.status, detail, retryable: isKeyFailoverError(response.status, payload, raw) }
    }
    const content = payload?.choices?.[0]?.message?.content
    const parsed = parseVerdict(content)
    if (parsed === undefined) {
      return { ok: false, model, status: 200, detail: String(content ?? 'empty vision response').slice(0, 500), retryable: false }
    }
    return {
      ok: true,
      value: {
        model,
        status: normalizeVerdict(parsed.verdict),
        summary: typeof parsed.summary === 'string' ? parsed.summary.slice(0, 500) : '',
        issues: Array.isArray(parsed.issues)
          ? parsed.issues.filter(issue => typeof issue === 'string').slice(0, 8)
          : [],
      },
    }
  } catch (error) {
    return {
      ok: false,
      model,
      status: 0,
      detail: error instanceof Error ? error.message : String(error),
      retryable: false,
    }
  } finally {
    clearTimeout(timer)
    signal.removeEventListener('abort', forwardAbort)
  }
}

/**
 * Ask the vision models to check one generated image. For each configured key,
 * try the primary model with the temporary URL, then a Base64 data URL, then
 * the lighter model with both payloads. A key that is rate-limited or out of
 * quota moves to the next key; a 400 on every attempt is an unsupported
 * payload/model and is skipped quietly.
 */
async function verifyImage({ baseURL, apiKeys, prompt, imageUrl, imageBytes, mediaType, signal, timeoutMs }) {
  const dataUrl = imageBytes === undefined
    ? undefined
    : `data:${mediaType};base64,${Buffer.from(imageBytes).toString('base64')}`
  const attempts = []
  for (const model of VISION_MODELS) {
    if (typeof imageUrl === 'string' && imageUrl !== '') attempts.push({ model, url: imageUrl })
    if (dataUrl !== undefined) attempts.push({ model, url: dataUrl })
  }
  for (const apiKey of apiKeys) {
    let last
    let keyRetryable = false
    for (const attempt of attempts) {
      last = await requestVision({
        baseURL,
        apiKey,
        model: attempt.model,
        imageUrl: attempt.url,
        prompt,
        signal,
        timeoutMs,
      })
      if (last.ok) return last.value
      if (last.retryable) {
        keyRetryable = true
        break
      }
      if (last.status !== 400) break
    }
    if (keyRetryable) continue
    if (last !== undefined && last.status !== 400) {
      return { model: last.model, status: 'error', summary: last.detail }
    }
  }
  return undefined
}

/** Download, save, and optionally visually verify every image in one API response. */
async function saveImages({ ctx, config, payload, prompt, format, verify, signal, agent, filename, baseURL, apiKeys }) {
  const session = agent?.session
  const cwd = session !== undefined
    ? ctx.workingDirectory.get(session)
    : ctx.workingDirectory.defaultDirectory
  const outputDirectory = liveConfig(config, 'outputDir', DEFAULT_OUTPUT_DIR) || DEFAULT_OUTPUT_DIR
  const directory = isAbsolute(outputDirectory) ? outputDirectory : resolve(cwd, outputDirectory)
  await mkdir(directory, { recursive: true })

  const stem = safeStem(filename ?? prompt, 'image')
  const stamp = new Date().toISOString().replace(/[:.]/gu, '-')
  const images = []
  for (const [index, item] of payload.data.entries()) {
    const bytes = await readImageBytes(item, signal)
    const path = join(directory, `${stamp}-${stem}-${index + 1}-${randomUUID().slice(0, 8)}.${format}`)
    await writeFile(path, bytes)
    const image = {
      path,
      bytes: bytes.byteLength,
      markdown: `[SenseNova image](<${path}>)`,
      ...(typeof item.url === 'string' && item.url !== '' ? { url: item.url } : {}),
    }
    if (verify) {
      const imageUrl = typeof item.url === 'string' && item.url !== ''
        ? item.url
        : `data:${OUTPUT_FORMATS[format]};base64,${bytes.toString('base64')}`
      image.verification = await verifyImage({
        baseURL,
        apiKeys,
        prompt,
        imageUrl,
        imageBytes: bytes,
        mediaType: OUTPUT_FORMATS[format],
        signal,
        timeoutMs: VISION_TIMEOUT_MS,
      })
    }
    images.push(image)
  }
  return images
}

const IMAGE_OUTPUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    model: { type: 'string', required: true },
    prompt: { type: 'string', required: true },
    size: { type: 'string', required: true },
    images: {
      type: 'array',
      required: true,
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          path: { type: 'string', required: true },
          bytes: { type: 'integer', required: true },
          markdown: { type: 'string', required: true },
          url: { type: 'string' },
          verification: {
            type: 'object',
            additionalProperties: false,
            properties: {
              model: { type: 'string', required: true },
              status: { type: 'string', required: true, enum: ['pass', 'warn', 'fail', 'error'] },
              summary: { type: 'string' },
              issues: { type: 'array', items: { type: 'string' } },
            },
          },
        },
      },
    },
  },
}

function renderImageResult(_args, value) {
  const lines = [
    `Generated ${value.images.length} image(s) with ${value.model} at ${value.size}.`,
    'The plugin already performed the visual check; use the `verification` field. Do not read the image with the session model.',
  ]
  for (const image of value.images) {
    lines.push(`- ${image.path} (${image.bytes} bytes)`)
    if (image.url !== undefined) lines.push(`  Temporary URL (24h): ${image.url}`)
    if (image.verification !== undefined) {
      lines.push(`  Visual check (${image.verification.model}): ${image.verification.status} — ${image.verification.summary ?? ''}`)
      if (Array.isArray(image.verification.issues) && image.verification.issues.length > 0) {
        lines.push(`  Issues: ${image.verification.issues.join('; ')}`)
      }
    } else {
      lines.push('  Visual check: disabled')
    }
  }
  return [{ type: 'text', text: lines.join('\n') }]
}

const PROMPT_SKILL_NAME = 'sensenova-prompt'
const PROMPT_SKILL_TEXT = `# SenseNova 文生图提示词规范

## 目标

把用户的模糊想法补全成可执行的画面指令；先给用户确认稿，确认后再生成，减少反复抽卡。

## 何时使用

在调用 sensenova_generate_image 或 sensenova_edit_image 之前使用。用户提出生成、画、设计、做海报/封面/信息图/插画/人像/产品图，或编辑已有图片时，先按本规范核对提示词。

## 工作流

1. 判断交付物类型：海报、信息图、插画、摄影、人像、产品图、编辑。
2. 用“九维清单”核对；已经清楚的维度不要重复扩写。
3. 缺少关键信息时，先补全或提出 1-3 个关键问题；不要凭空编造品牌、人物、数据或精确文字。
4. 给用户一份确认稿：画面目标、建议提示词、需要确认的选项。
5. 默认先给确认稿；只有用户明确说“直接生成”或“不用确认”时才跳过确认。用户说“帮我生成”不等于“直接生成”。
6. 生成后用插件返回的 verification 做核对；不要用会话模型读图。

## 九维清单

1. 交付物与用途：海报、信息图、插画、摄影、人像、产品图、封面、编辑。
2. 画幅与尺寸：比例（1:1、3:4、9:16、16:9、A4 等）、分辨率、横竖版。
3. 风格与媒介：版画、水彩、胶片摄影、3D、极简矢量、拼贴、国风、赛博朋克等；说明参考方向，不要只写“高级感”。
4. 主体与动作：谁/什么、数量、外观、服装、动作、表情、状态；产品图要写材质和卖点。
5. 构图与镜头：主体位置、视角、景别、镜头、景深、留白、网格、前后景关系。
6. 色彩与光线：主色、辅色、色温、光源方向、明暗、材质纹理、颗粒/噪点。
7. 文字与排版：精确文案（用引号）、语言、字体气质、字号层级、位置、横竖排；信息图要写章节和图表类型。
8. 氛围与受众：情绪、场景、平台调性、品牌气质、使用场景。
9. 限制与负面项：不要水印、不要多余文字、不要畸形手指、不要改变主体身份、必须保留的元素。

## 模板

海报：画幅 + 用途 + 风格/媒介 + 主题/主体 + 构图/版式 + 文字层级 + 配色/光线 + 质感/氛围 + 限制。

信息图：尺寸/比例 + 信息图类型 + 主题/受众 + 章节/数据 + 版式/网格 + 图表类型 + 配色/字体 + 文字要求 + 限制。

插画/摄影：比例 + 媒介/风格 + 主体/动作 + 环境 + 镜头/构图 + 光线/色彩 + 情绪 + 限制。

人像：比例 + 摄影/胶片风格 + 人物/服装/姿态 + 场景 + 镜头/景深 + 光线 + 色调 + 质感 + 限制。

摄影：画幅 + 机位/镜头 + 人物/姿态 + 服装/道具 + 环境 + 光线方向/色温 + 景深/运动模糊 + 胶片/颗粒 + 色调 + 限制。

插画：画幅 + 媒介/笔触 + 线条/纹理 + 主体/动作 + 构图/视角 + 色彩 + 情绪 + 限制。

信息图/海报：画幅 + 背景/主色 + 品牌/标题/副标题/英文小字层级 + 主视觉位置 + 装饰元素 + 排版/留白 + 光影 + 限制。

编辑：保留什么 + 修改什么 + 参考图角色（主图/风格/元素）+ 一致性要求 + 禁止改变的部分。

## 画廊示例的写法（U1 Pro + U1.6 Lite）

- 城市海报：竖幅 9:16，版画木刻，黑+橘红双色，白底颗粒噪点；主体两座古塔与提线木偶；顶部大标题、右侧竖排城市名、右下角印章；构图饱满。
- 节气海报：竖版 3:4，清新现代平面设计，轻微复古印刷感；天空蓝+草坡绿+西瓜红；天空留白与分散字母、风筝、细白引导线；底部大号日期排版。
- 摄影信息图：A4 竖版，极简矢量，暖白底，黑/深灰/银灰为主，少量暖棕强调；顶部标题、中部主视觉、左右知识模块；所有文字中文，不要英文、乱码、水印。
- 时尚人像：中画幅时尚摄影，中法混血女模特，白缎花饰礼服，T 台走秀，闪光灯，背景虚化，高级时装杂志质感。
- 简短需求：用户只说“武康路，社交媒体风格，有网感”时，不要硬扩成 500 字；先问平台/比例、是否要文字、想要的色调，再给 2-3 句可执行提示词。

### U1.6 Lite 画廊特点（100 个示例）

- 摄影 42、插画 32、信息图 26；提示词中位数 367 字，平均 428 字。
- 摄影：写清机位/镜头、人物姿态、服装道具、光线方向、景深/运动模糊、胶片颗粒和色调。
- 插画：写清媒介（水彩/蜡笔/粉彩）、线条、纹理、主色、构图和情绪。
- 信息图/海报：写清画幅、背景、品牌/标题/副标题/英文小字的层级、主视觉位置、装饰元素和留白。

- 摄影示例：竖幅侧向跟拍，人物从左向右跑，头微低，长发向后翻；一大捧黄花横在胸前，黑外套与短下装；金色逆光描亮发梢，脚部方向性模糊，背景楼面只留带状色影，明显胶片颗粒。
- 插画示例：柔和的水彩与蜡笔混合，线条圆润；巨大粉猫趴卧，小女孩坐在猫肚子上看书；中近景略俯视，暖色、安静、童话感。
- 信息图/海报示例：2:3 竖版，深浅明绿的水雾背景；顶部中央小号绿色衬线品牌，约四分之一处深绿书法标题，下接细宋体和两行英文小字；蛋糕居中偏下，玻璃高脚盘，浅黄青绿奶油条纹，桌面同心水波纹。
- 版式示例：先拍 3:2 城市街头横幅，再合成 3:4 白底画布，横向照片贴满全宽、垂直居中、上下各留四分之一白边，不在白边加字。

## 规则

- 具体名词和动词优先于空泛形容词；不要堆砌“masterpiece、8K、best quality”。
- 文字必须用引号给出精确内容；说明语言、字体气质、位置和层级；不额外添加无关文字。
- 信息图不要编造数据；数据由用户提供，或明确标注为示意。
- 编辑时先写“必须保留”，再写“需要改变”；参考图第一张是主图。
- 简单需求保持简短；海报/信息图/多主体场景才需要结构化长提示词。
- U1.6 Lite 的摄影/插画/信息图示例普遍较长；这类请求要写足镜头、光线、媒介、文字层级，不要只写一句主题。
- 先确认再生成；确认稿要能让用户直接改，不要只给一句“我来优化”。

## 确认话术

我先按规范补全提示词，确认后再生成：

- 交付物：……
- 建议提示词：……
- 需要你确认：比例 / 文字 / 风格 / 是否保留某元素

用户确认或说“直接生成”后，再调用 sensenova_generate_image 或 sensenova_edit_image。`

const IMAGE_POLICY_TEXT = `## Image generation policy

When the user asks to generate, create, draw, design, or render an image — including illustrations, posters, covers, icons, infographics, product shots, photos, avatars, or visual assets — call \`sensenova_generate_image\` first. If the user supplies reference images or asks to edit/rewrite an existing image, call \`sensenova_edit_image\` instead. Do not substitute HTML/CSS/SVG/canvas rendering or a web image search for a generation request unless the user explicitly asks for HTML/vector code, or the image tool is unavailable or fails. Use web search only to find existing images or references, not to fulfill a request to create one. For a web page or UI, use the appropriate frontend/HTML workflow; for an image asset or a visual to be placed into a page, use this tool. Posters and infographics with text should use this tool too; only use HTML when the user asks for editable HTML. If no API key is configured or the tool fails, say so and ask how to proceed instead of silently switching to HTML or search. After a SenseNova image tool returns, use its \`verification\` field for the visual check. Do not call \`read_image\` or another image-reading tool on the generated file with the session model; the session model may not accept images. Only read the image again if the user explicitly asks and the current model supports image input. For \`sensenova_edit_image\`, pass reference images as public URLs, data URLs, or local file paths; the plugin reads local paths, so the session model does not need image input. Before calling a SenseNova image tool, load the \`sensenova-prompt\` skill. For a new image request, check the prompt against its nine-dimension checklist; if key details are missing, present the completed prompt and ask the user to confirm or edit it, then generate. Do not call the image tool before that confirmation unless the user explicitly says '直接生成' or '不用确认'.`

export function apply(ctx, config) {
  const baseURL = textConfig(config, 'baseURL', DEFAULT_BASE_URL)
  const apiKeyEnv = textConfig(config, 'apiKeyEnv', DEFAULT_API_KEY_ENV)
  const requestTimeoutMs = numberConfig(config, 'requestTimeoutMs', DEFAULT_REQUEST_TIMEOUT_MS)

  // This bundle ships its own settings section; keep the schema-derived form off.
  ctx.inject(['settings'], (settingsCtx) => {
    settingsCtx.effect(() => settingsCtx.settings.configure({ auto: false }, ctx.fiber))
  })

  ctx.inject(['systemPrompt'], (promptCtx) => {
    promptCtx.effect(() => promptCtx.systemPrompt.section({
      name: 'sensenova:image-policy',
      order: 700,
      text: IMAGE_POLICY_TEXT,
    }))
  })

  ctx.inject(['skills'], (skillsCtx) => {
    skillsCtx.effect(() => skillsCtx.skills.register({
      name: PROMPT_SKILL_NAME,
      description: 'Draft, check, and expand SenseNova text-to-image prompts; confirm with the user before generating.',
      whenToUse: 'Use before sensenova_generate_image or sensenova_edit_image whenever the user asks for an image.',
      content: PROMPT_SKILL_TEXT,
      source: 'runtime',
      invocation: { modelInvocable: true, userInvocable: true },
    }))
  })

  ctx.tools.register(defineTool({
    name: 'sensenova_generate_image',
    description:
      'Use this tool whenever the user asks to generate, create, draw, design, or render an image '
      + '(illustration, poster, cover, icon, infographic, product shot, photo, avatar, visual asset). '
      + 'Prefer it over HTML/CSS/SVG/canvas rendering or web image search; use search only to find existing images. '
      + 'Generate one or more images from a text prompt with SenseNova U1.6 Lite (sensenova-u1.6-lite). '
      + 'After saving each image, SenseNova 6.8 Flash (sensenova-6.8-flash) checks it against the prompt and '
      + 'reports pass/warn/fail plus issues; a failed check does not discard the image. '
      + 'Use the returned `verification` field; do not read the generated image with the session model. '
      + 'Before calling this tool, load the sensenova-prompt skill and confirm the expanded prompt with the user unless they explicitly said to generate immediately. '
      + 'The image model is an image-generation model, not a chat model. Images are downloaded and saved in the '
      + 'session working directory; the result contains each absolute path, byte size, temporary URL, a normal '
      + 'file link, and the visual-check result. Do not add a Markdown image embed. Use this tool for any '
      + 'text-to-image request, such as illustrations, posters, product shots, or '
      + 'infographics. Size, n, watermark, prompt_extend, self_correction, verify, and output_format default to '
      + 'the values on the plugin settings page; explicit parameters override them.',
    parameters: {
      prompt: {
        type: 'string',
        required: true,
        description: 'Image description. Chinese and English are both supported; longer, more specific prompts work well.',
      },
      size: {
        type: 'string',
        description: 'Output size: "auto" (default), "2K", "4K", or WIDTHxHEIGHT. Width and height must be 512-4096, multiples of 32, and no more than 3:1 apart. Omit to use the settings page default.',
      },
      n: {
        type: 'integer',
        description: `Number of images to generate, 1-${MAX_IMAGES}. Omit to use the settings page default.`,
      },
      watermark: {
        type: 'boolean',
        description: 'Add the provider watermark. Omit to use the settings page default.',
      },
      prompt_extend: {
        type: 'boolean',
        description: 'Automatically polish/expand the prompt; the provider falls back to the original prompt if expansion fails. Omit to use the settings page default.',
      },
      self_correction: {
        type: 'boolean',
        description: 'Improve text accuracy and overall image quality (self_correction). Omit to use the settings page default.',
      },
      verify: {
        type: 'boolean',
        description: 'Check each generated image with sensenova-6.8-flash. Omit to use the settings page default.',
      },
      output_format: {
        type: 'string',
        enum: ['png', 'jpeg', 'webp'],
        description: 'Saved image format. Omit to use the settings page default.',
      },
      filename: {
        type: 'string',
        description: 'Optional base name for the saved file; the extension and a uniqueness suffix are added automatically.',
      },
    },
    output: {
      schema: IMAGE_OUTPUT_SCHEMA,
      render: renderImageResult,
    },
    timeoutMs: TOOL_TIMEOUT_MS,
    async execute(args, exec) {
      exec.signal.throwIfAborted()

      const prompt = args.prompt.trim()
      if (prompt === '') throw new ToolArgsError(['prompt must not be blank'])

      const selectedModel = DEFAULT_MODEL
      const verify = args.verify ?? liveConfig(config, 'verify', true)
      const size = normalizeSize(args.size ?? liveConfig(config, 'size', 'auto'))
      const n = args.n ?? liveConfig(config, 'n', 1)
      if (!Number.isInteger(n) || n < 1 || n > MAX_IMAGES) {
        throw new ToolArgsError([`n must be an integer from 1 to ${MAX_IMAGES}`])
      }
      const format = args.output_format ?? liveConfig(config, 'output_format', 'png')
      if (!Object.hasOwn(OUTPUT_FORMATS, format)) {
        throw new ToolArgsError(['output_format must be png, jpeg, or webp'])
      }

      const keyPreference = liveConfig(config, 'keyPreference', 'custom')
      const apiKeys = await resolveApiKeys(ctx, apiKeyEnv, keyPreference)
      const body = {
        model: selectedModel,
        prompt,
        n,
        size,
        output_format: format,
        response_format: 'url',
        watermark: args.watermark ?? liveConfig(config, 'watermark', false),
        prompt_extend: args.prompt_extend ?? liveConfig(config, 'prompt_extend', true),
        self_correction: args.self_correction ?? liveConfig(config, 'self_correction', true),
      }

      const generated = await requestImages({
        baseURL,
        apiKeys,
        path: '/images/generations',
        body,
        signal: exec.signal,
        timeoutMs: requestTimeoutMs,
      })
      const payload = generated.payload
      const imageKey = generated.apiKey
      if (imageKey !== apiKeys[0]) {
        const customKey = await resolveKeyRef(ctx, USER_API_KEY_ENV)
        const fallbackKey = await resolveKeyRef(ctx, apiKeyEnv)
        await persistKeyPreference(ctx, imageKey, customKey, fallbackKey)
      }

      const images = await saveImages({
        ctx,
        config,
        payload,
        prompt,
        format,
        verify,
        signal: exec.signal,
        agent: exec.agent,
        filename: args.filename,
        baseURL,
        apiKeys: [imageKey, ...apiKeys.filter(key => key !== imageKey)],
      })

      return {
        model: selectedModel,
        prompt,
        size: typeof payload.size === 'string' && payload.size !== '' ? payload.size : size,
        images,
      }
    },
  }))



  ctx.tools.register(defineTool({
    name: 'sensenova_edit_image',
    description:
      'Use this tool when the user supplies reference images or asks to edit/rewrite an existing image. '
      + 'Edit or rewrite one or more reference images with SenseNova U1.6 Lite (sensenova-u1.6-lite). '
      + 'Pass 1-5 reference images as public URLs, Base64 data URLs, or local file paths; local paths are read by the plugin, so the session model does not need image input. The first is the primary image. '
      + 'After saving the result, SenseNova 6.8 Flash (sensenova-6.8-flash) checks it against the edit prompt '
      + 'and returns a `verification` field. Use that field; do not read the generated image with the session model. '
      + 'Before calling this tool, load the sensenova-prompt skill and confirm the expanded prompt with the user unless they explicitly said to generate immediately. '
      + 'Use this tool for image-to-image editing, style transfer, background replacement, object changes, '
      + 'or reference-guided generation. Size, watermark, prompt_extend, self_correction, verify, and '
      + 'output_format default to the settings page.',
    parameters: {
      prompt: {
        type: 'string',
        required: true,
        description: 'Editing instruction describing the expected final image.',
      },
      images: {
        type: 'array',
        required: true,
        items: { type: 'string' },
        description: `1-${MAX_REFERENCE_IMAGES} reference images. Each may be a public HTTPS URL, a Base64 data URL (data:image/png;base64,...), or a local file path (png/jpeg/webp). Local paths are read by the plugin, so the session model does not need image input. The first image is the primary image.`,
      },
      size: {
        type: 'string',
        description: 'Output size: "auto" (default, follows the primary image), "2K", "4K", or WIDTHxHEIGHT. Width and height must be 512-4096, multiples of 32, and no more than 3:1 apart. Omit to use the settings page default.',
      },
      watermark: {
        type: 'boolean',
        description: 'Add the provider watermark. Omit to use the settings page default.',
      },
      prompt_extend: {
        type: 'boolean',
        description: 'Automatically polish/expand the edit prompt; the provider falls back to the original prompt if expansion fails. Omit to use the settings page default.',
      },
      self_correction: {
        type: 'boolean',
        description: 'Improve text accuracy and overall image quality (self_correction). Omit to use the settings page default.',
      },
      verify: {
        type: 'boolean',
        description: 'Check the edited image with sensenova-6.8-flash. Omit to use the settings page default.',
      },
      output_format: {
        type: 'string',
        enum: ['png', 'jpeg', 'webp'],
        description: 'Saved image format. Omit to use the settings page default.',
      },
      filename: {
        type: 'string',
        description: 'Optional base name for the saved file; the extension and a uniqueness suffix are added automatically.',
      },
    },
    output: {
      schema: IMAGE_OUTPUT_SCHEMA,
      render: renderImageResult,
    },
    timeoutMs: TOOL_TIMEOUT_MS,
    async execute(args, exec) {
      exec.signal.throwIfAborted()

      const prompt = args.prompt.trim()
      if (prompt === '') throw new ToolArgsError(['prompt must not be blank'])
      const references = Array.isArray(args.images)
        ? args.images.map(item => String(item).trim()).filter(item => item !== '')
        : []
      if (references.length < 1 || references.length > MAX_REFERENCE_IMAGES) {
        throw new ToolArgsError([`images must contain 1-${MAX_REFERENCE_IMAGES} reference images`])
      }

      const verify = args.verify ?? liveConfig(config, 'verify', true)
      const size = normalizeSize(args.size ?? liveConfig(config, 'size', 'auto'))
      const format = args.output_format ?? liveConfig(config, 'output_format', 'png')
      if (!Object.hasOwn(OUTPUT_FORMATS, format)) {
        throw new ToolArgsError(['output_format must be png, jpeg, or webp'])
      }

      const resolvedReferences = []
      for (const reference of references) {
        resolvedReferences.push(await resolveReferenceImage(reference, ctx, exec.agent?.session))
      }

      const keyPreference = liveConfig(config, 'keyPreference', 'custom')
      const apiKeys = await resolveApiKeys(ctx, apiKeyEnv, keyPreference)
      const body = {
        model: DEFAULT_MODEL,
        images: resolvedReferences.map(imageUrl => ({ image_url: imageUrl })),
        prompt,
        n: 1,
        size,
        output_format: format,
        response_format: 'url',
        watermark: args.watermark ?? liveConfig(config, 'watermark', false),
        prompt_extend: args.prompt_extend ?? liveConfig(config, 'prompt_extend', true),
        self_correction: args.self_correction ?? liveConfig(config, 'self_correction', true),
      }

      const generated = await requestImages({
        baseURL,
        apiKeys,
        path: '/images/edits',
        body,
        signal: exec.signal,
        timeoutMs: requestTimeoutMs,
      })
      const payload = generated.payload
      const imageKey = generated.apiKey
      if (imageKey !== apiKeys[0]) {
        const customKey = await resolveKeyRef(ctx, USER_API_KEY_ENV)
        const fallbackKey = await resolveKeyRef(ctx, apiKeyEnv)
        await persistKeyPreference(ctx, imageKey, customKey, fallbackKey)
      }

      const images = await saveImages({
        ctx,
        config,
        payload,
        prompt,
        format,
        verify,
        signal: exec.signal,
        agent: exec.agent,
        filename: args.filename,
        baseURL,
        apiKeys: [imageKey, ...apiKeys.filter(key => key !== imageKey)],
      })

      return {
        model: DEFAULT_MODEL,
        prompt,
        size: typeof payload.size === 'string' && payload.size !== '' ? payload.size : size,
        images,
      }
    },
  }))
}
